from __future__ import annotations; import ast; from pathlib import Path; import pytest; import common.meta.extension.check_package_contract as cpc; from common.meta import ACRecord, ConceptRecord, Kind, PackageContract, Unit, ac_vision_index, concept_index, contract_index; from common.meta.extension.check_package_contract import DiscoveredPackage; REPO = Path(__file__).resolve().parents[2]; META = REPO / 'common/meta'  # AC-meta.event.1
def _imported_modules(path: Path) -> set[str]: mods: set[str] = set(); [mods.add(node.module) if isinstance(node, ast.ImportFrom) and node.module else mods.update((a.name for a in node.names)) if isinstance(node, ast.Import) else None for node in ast.walk(ast.parse(path.read_text(encoding='utf-8')))]; return mods
def _contract(name: str, **overrides: object) -> PackageContract: kwargs: dict[str, object] = {'name': name, 'klass': 'infra', 'tier': 'CODE-ONLY', 'depends_on': [], 'interface': [], 'events': [], 'invariants': [], 'roadmap': [], 'units': []}; kwargs.update(overrides); return PackageContract(**kwargs)
def _make_pkg(tmp: Path, name: str, *, units: list[Unit], layered: bool=True, extra_files: dict[str, str] | None=None) -> DiscoveredPackage:
    impl = tmp / 'apps/backend/src' / name; impl.mkdir(parents=True); (impl / '__init__.py').write_text('__all__ = []\n', encoding='utf-8')
    if layered:
        for layer in ('base', 'extension'): (impl / layer).mkdir(); (impl / layer / '__init__.py').write_text('', encoding='utf-8')
    for (rel, content) in (extra_files or {}).items(): path = impl / rel; path.parent.mkdir(parents=True, exist_ok=True); path.write_text(content, encoding='utf-8')
    contract = _contract(name, units=units, implementations={'be': f'apps/backend/src/{name}', 'fe': None}); return DiscoveredPackage(name=name, spec_dir=tmp / 'common' / name, impl_dir=impl, contract=contract)
def test_meta_converges_by_layer():
    assert (META / 'base/package_contract.py').exists(); assert (META / 'extension/check_package_contract.py').exists(); assert (META / 'data/projection.py').exists(); exports = (META / '__init__.py').read_text(encoding='utf-8')
    for name in ('PackageContract', 'Kind', 'Unit', 'contract_index'): assert name in exports, f'meta must export {name}'
def test_meta_base_is_pure():
    offenders: dict[str, set[str]] = {}
    for path in sorted((META / 'base').rglob('*.py')):
        bad = {m for m in _imported_modules(path) if m.startswith('common.meta.extension') or m.startswith('common.meta.data') or 'sqlalchemy' in m}
        if bad: offenders[str(path.relative_to(META))] = bad
    assert not offenders, f'meta base/ reaches into extension/data/ORM: {offenders}'; _m1_dup = ACRecord(id='AC-dup.1.1', statement='s', test='t::f', priority='P0', status='done'); _m1_a = _contract('a', roadmap=[_m1_dup]); _m1_b = _contract('b', roadmap=[_m1_dup])
    with pytest.raises(ValueError, match='claimed by two packages'): contract_index([_m1_a, _m1_b])
