def test_AC_meta_projection_1_contract_index_is_pure(tmp_path: Path): 'AC-meta.projection.1'; a = _contract('a', units=[Unit(name='V', kind=Kind.VALUE_OBJECT, module='base/v.py')]); b = _contract('b', klass='middleware', depends_on=['a'], roadmap=[ACRecord(id='AC-b.1.1', statement='s', test='t::f', priority='P0', status='done')], units=[Unit(name='R', kind=Kind.REPOSITORY, module='base/p.py', impl='extension/s.py')]); idx = contract_index([a, b]); assert idx['registry']['a']['klass'] == 'infra'; assert idx['consumers']['a'] == ['b']; assert idx['ac_index']['AC-b.1.1'] == 'b'; assert idx['units_by_layer']['a'] == {'base': 1, 'extension': 0, 'data': 0}; assert idx['units_by_layer']['b'] == {'base': 1, 'extension': 1, 'data': 0}; assert contract_index([a, b]) == idx; 'AC-meta.concept.1'; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); 'AC-meta.concept.1'; _m3_a = _contract('a', concepts=[ConceptRecord(key='widget_shape', owner='common/a/readme.md#widget-shape', description='What a widget is.', cross_refs=['AGENTS.md'], proofs=['tests/a/test_widget.py'], family='platform')]); _m3_b = _contract('b', klass='middleware', depends_on=['a']); _m3_idx = concept_index([_m3_a, _m3_b]); assert _m3_idx == {'widget_shape': {'owner': 'common/a/readme.md#widget-shape', 'description': 'What a widget is.', 'cross_refs': ['AGENTS.md'], 'proofs': ['tests/a/test_widget.py'], 'family': 'platform', 'kind': None, 'authority': None, 'parent': None}}; assert concept_index([_m3_a, _m3_b]) == _m3_idx
def test_AC_meta_vision_anchor_1_projection_is_pure():
    'AC-meta.vision-anchor.1'; anchored = ACRecord(id='AC-a.vision.1', statement='Back the declared product decision.', test='tests/a/test_vision.py::test_anchor', priority='P0', status='done', vision_anchor='decision-a'); unanchored = ACRecord(id='AC-b.other.1', statement='No vision declaration.', test='tests/b/test_other.py::test_other', priority='P1', status='done', vision_anchor=None); contracts = [_contract('a', roadmap=[anchored]), _contract('b', klass='middleware', roadmap=[unanchored])]; assert ac_vision_index(contracts) == {'AC-a.vision.1': 'decision-a'}; assert ac_vision_index(contracts) == ac_vision_index(contracts); 'AC-meta.vision-anchor.1'; 'AC-meta.vision-anchor.1'
